class Mobile {
    String brand;
    double price;
}

public class Main {
    public static void main(String[] args) {
        Mobile m = new Mobile();
        m.brand = "Pixel 8";
        m.price = 699.99;
        System.out.println("Purchased " + m.brand + " for $" + m.price);
    }
}

class Dog {
    String name;

    void bark() {
        System.out.println(name + " says Woof!");
    }
}

public class Main {
    public static void main(String[] args) {
        Dog d = new Dog();
        d.name = "Buddy";
        d.bark();
    }
}
